body.push(...FONTE('IBGE, Censo Demográfico 2022 (tabela 10150). Elaboração própria.',['Taxa de escolarização: percentual de estudantes na população do grupo de idade. O total refere-se às pessoas de 6 anos ou mais de idade.']));
body.push(P(`O Censo contabiliza ${n0(estAP('Total','Total').tea)} estudantes com diagnóstico de autismo no Amapá, ${pc1(estAP('Total','Total').pct)} de todos os estudantes de 6 anos ou mais (Brasil: ${pc1(estBR('Total','Total').pct)}). Na faixa de 6 a 14 anos são ${n0(estAP('Total','6 a 14 anos').tea)} estudantes (${pc1(estAP('Total','6 a 14 anos').pct)} das matrículas nessa idade), ${n0(estAP('Total','15 a 17 anos').tea)} entre 15 e 17 anos, ${n0(estAP('Total','18 a 24 anos').tea)} entre 18 e 24 anos e ${n0(estAP('Total','25 anos ou mais').tea)} com 25 anos ou mais. Entre os estudantes homens a proporção com diagnóstico chega a ${pc1(estAP('Homens','Total').pct)}. Macapá concentra ${n0(macapa.estudantes_tea)} desses estudantes e Santana ${n0(santana.estudantes_tea)} (Tabela 6). Esses números dimensionam a necessidade de Atendimento Educacional Especializado, de profissionais de apoio escolar (Brasil, 2012, art. 3º, parágrafo único) e de formação docente.`));
body.push(H2('6.1 Escolaridade dos adultos'));
body.push(P(`Entre as pessoas de 25 anos ou mais com diagnóstico de autismo no Amapá, ${pc1(R.instrucao.UF.tea['Sem instrução e fundamental incompleto'])} não têm instrução ou têm fundamental incompleto, contra ${pc1(R.instrucao.UF.geral['Sem instrução e fundamental incompleto'])} da população geral da mesma idade; apenas ${pc1(R.instrucao.UF.tea['Superior completo'])} têm ensino superior completo (geral: ${pc1(R.instrucao.UF.geral['Superior completo'])}). O padrão é semelhante ao nacional (Tabela 8) e evidencia que as gerações adultas, diagnosticadas tardiamente ou nunca apoiadas na escola, acumulam déficit educacional importante, com implicações para inserção produtiva e autonomia.`));
const NI=['Sem instrução e fundamental incompleto','Fundamental completo e médio incompleto','Médio completo e superior incompleto','Superior completo'];
body.push(TABTITLE('Distribuição percentual das pessoas de 25 anos ou mais de idade, com autismo e da população geral, segundo o nível de instrução - Amapá e Brasil - 2022'));
body.push(TBL(['Nível de instrução','Amapá - com autismo (%)','Amapá - população geral (%)','Brasil - com autismo (%)','Brasil - população geral (%)'],NI.map(k=>[k,p1(R.instrucao.UF.tea[k]),p1(R.instrucao.UF.geral[k]),p1(R.instrucao.BR.tea[k]),p1(R.instrucao.BR.geral[k])]).concat([['Total','100,0','100,0','100,0','100,0']]),[3471,1400,1400,1400,1400],{font:20,bold:(t,i)=>i===0&&t==='Total'}));
